package com.lifeos.habits;import com.lifeos.habits.dto.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.core.userdetails.UserDetails;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/habits")public class HabitController{private final HabitService s;public HabitController(HabitService s){this.s=s;}@GetMapping public List<HabitResponse>list(@AuthenticationPrincipal UserDetails p){return s.list(p.getUsername());}@GetMapping("/{id}")public HabitResponse get(@PathVariable Long id,@AuthenticationPrincipal UserDetails p){return s.get(id,p.getUsername());}@PostMapping@ResponseStatus(HttpStatus.CREATED)public HabitResponse create(@Valid@RequestBody HabitRequest r,@AuthenticationPrincipal UserDetails p){return s.create(r,p.getUsername());}@PutMapping("/{id}")public HabitResponse update(@PathVariable Long id,@Valid@RequestBody HabitRequest r,@AuthenticationPrincipal UserDetails p){return s.update(id,r,p.getUsername());}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void delete(@PathVariable Long id,@AuthenticationPrincipal UserDetails p){s.delete(id,p.getUsername());}}
